// Whitelist explicita (regra permanente do projeto): nunca passthrough
// direto do jsonb da RPC, mesmo quando parece seguro hoje.
const row = $input.first()?.json?.resultado || {};
const carrinho = row.carrinho || { itens: [], valor_total: 0 };
const itens = Array.isArray(row.itens) ? row.itens : [];
const saida = {
  itens: itens.map(i => ({
    autorizado: !!i.autorizado,
    motivo: i.motivo || null,
    produto_id: i.produto_id,
    produto_nome: i.produto_nome,
    quantidade_antes: i.quantidade_antes,
    quantidade_final: i.quantidade_final,
  })),
  carrinho: {
    vazio: carrinho.itens ? carrinho.itens.length === 0 : true,
    itens: (carrinho.itens || []).map(i => ({
      produto_id: i.produto_id, nome: i.nome, quantidade: i.quantidade,
      preco_unitario: i.preco_unitario, subtotal: i.subtotal,
    })),
    valor_total: carrinho.valor_total,
  },
};
return [{ json: saida }];

function tryGet(name) {
  try { return $(name).item.json; } catch (e) { return null; }
}
const trigger = $('When Executed by Another Workflow').item.json;
const resultado = tryGet('Montar Resultado');
return [{ json: {
  empresa_id: trigger.p_empresa_id,
  conversa_id: trigger.p_conversa_id || null,
  mensagem_id: trigger.p_mensagem_id || null,
  atendimento_id: trigger.p_atendimento_id || null,
  tool_nome: 'repetir_pedido',
  detalhes: JSON.stringify({ input: { p_pedido_id: trigger.p_pedido_id, p_tipo_mensagem: trigger.p_tipo_mensagem }, output: resultado }),
  resultado_original: resultado,
} }];
